param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'file-load-exception-rendering-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$constructors=@{};foreach($entry in @(@{key='default';types=[type[]]@()},@{key='message';types=[type[]]@([string])},@{key='inner';types=[type[]]@([string],[Exception])},@{key='file';types=[type[]]@([string],[string])},@{key='file-inner';types=[type[]]@([string],[string],[Exception])})){$constructors[$entry.key]=[IO.FileLoadException].GetConstructor($entry.types)};$rows=[Collections.Generic.List[object]]::new();$nullArgumentControls=0
function Units($Value){if($null -eq $Value){return $null};return ,([int[]][char[]]$Value)}
for($index=0;$index -lt $plan.cases.Count;$index++){$spec=$plan.cases[$index];$message=$null;$fileName=$null;if($null -ne $plan.messages[$spec.messageIndex]){$message=[string]::new([char[]]([int[]]$plan.messages[$spec.messageIndex]))};if($null -ne $plan.files[$spec.fileIndex]){$fileName=[string]::new([char[]]([int[]]$plan.files[$spec.fileIndex]))};$inner=$null;if($spec.inner -eq 'plain'){$inner=[Exception]::new()}elseif($spec.inner -eq 'named'){$inner=[Exception]::new('inner')};switch($spec.route){'default'{$arguments=[object[]]::new(0)};'message'{$arguments=[object[]]::new(1);$arguments[0]=$message};'inner'{$arguments=[object[]]::new(2);$arguments[0]=$message;$arguments[1]=$inner};'file'{$arguments=[object[]]::new(2);$arguments[0]=$message;$arguments[1]=$fileName};'file-inner'{$arguments=[object[]]::new(3);$arguments[0]=$message;$arguments[1]=$fileName;$arguments[2]=$inner}};if($spec.route -ne 'default' -and $null -eq $message){if($null -ne $arguments[0]){throw 'Null message argument coerced'};$nullArgumentControls++};$e=$constructors[$spec.route].Invoke($arguments);$rows.Add([ordered]@{index=$index;messageUnits=(Units $e.Message);fileNameUnits=(Units $e.FileName);fusionLogUnits=(Units $e.FusionLog);hResult=$e.HResult;innerSame=[object]::ReferenceEquals($e.InnerException,$inner);toStringUnits=(Units ($e.ToString()))})}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';nullArgumentControls=$nullArgumentControls;rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 18 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS FileLoadException rendering: $($rows.Count) native constructors"
